import{_ as o,o as a,c as t,ae as n}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"Default behavior and platform changes","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/engine-modifications/09-behavior-changes.md","filePath":"explanation/engine-modifications/09-behavior-changes.md"}'),i={name:"explanation/engine-modifications/09-behavior-changes.md"};function r(s,e,l,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="default-behavior-and-platform-changes" tabindex="-1">Default behavior and platform changes <a class="header-anchor" href="#default-behavior-and-platform-changes" aria-label="Permalink to &quot;Default behavior and platform changes&quot;">​</a></h1><h2 id="behavior-changes" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h2><p>In addition to the functional extensions, the engine introduces behavior changes worth knowing about:</p><ul><li><strong>Variable time step by default</strong>: <code>VARIABLE_STEP</code> defaults to <strong>0.75</strong> (Courant-adaptive step), whereas the SWMM 5.x manual documents 0 (fixed step). To reproduce the official SWMM behavior, <code>VARIABLE_STEP 0</code> must be set.</li><li><strong>Tolerance unit handling</strong>: the <code>HEAD_TOLERANCE</code> and the <code>MIN_SURFAREA</code> are converted from the project units to the internal system (feet) at initialization, correcting factor 3.3–10.8 errors in SI models of the previous engine.</li><li><strong>Conduit losses per iteration</strong>: under dynamic wave, conduit evaporation and infiltration are recomputed in <em>every</em> Picard iteration (with the routing-class gate), as in the legacy engine, instead of once per step.</li><li><strong>Convergence counting</strong>: a step that converges on its last allowed attempt is counted as converged (it only fails if it does not converge after <code>MAX_TRIALS</code>).</li><li><strong>Steady-state skip</strong>: <code>SKIP_STEADY_STATE</code> skips the routing when there were no control actions, the continuity error is under tolerance and the inflows did not change.</li></ul><h2 id="platform-and-format-extensions" tabindex="-1">Platform and format extensions <a class="header-anchor" href="#platform-and-format-extensions" aria-label="Permalink to &quot;Platform and format extensions&quot;">​</a></h2><ul><li><strong>CRS</strong>: the <code>CRS</code> option in <code>[OPTIONS]</code> accepts an EPSG or a PROJ string, carrying the spatial reference system of the model (official SWMM does not have it).</li><li><strong>Extension keys</strong>: <code>ext_options</code> stores any unknown <code>[OPTIONS]</code> key for plugins.</li><li><strong>IGNORE_2D</strong>: allows disabling the 2D solver while keeping the mesh in the file (to run the model 1D only).</li><li><strong>Geopackage</strong>: native GeoPackage input/output (including the <code>rdii_decay</code> table of the recovery parameters), in addition to the <code>.inp</code> format.</li><li><strong>C API</strong>: a C API (with wrappers) exposes all the extensions (for example <code>swmm_rdii_decay_add</code>).</li><li><strong>WebAssembly</strong>: the engine is compiled to WASM to run in the browser (as LocalSWMM uses it), with the 2D solver on GPU/WebGPU.</li><li><strong>Manufactured solution tests</strong>: the repository includes a battery of benchmarks with analytical solutions (Ritter dam break, lake at rest, Macdonald waves, pump discharge reference curves, among others) that anchor the fidelity of the solvers.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Rossman, L. A. (2017). <em>Storm Water Management Model Reference Manual Volume II — Hydraulics</em>. U.S. EPA.</li><li>Sharior, S., Hodges, B. R., &amp; Vasconcelos, J. G. (2023). Generalized, dynamic, and transient-storage form of the Preissmann slot. <em>Journal of Hydraulic Engineering</em>, 149(11).</li><li>de Almeida, G. A. M., &amp; Bates, P. D. (2013). Applicability of the local inertial approximation of the shallow water equations to flood modeling. <em>Water Resources Research</em>, 49(8).</li><li>Source code of the OpenSWMM engine (HydroCouple): <ul><li><code>src/engine/hydraulics/DynamicWave.cpp</code>, <code>src/engine/hydraulics/HydStructures.cpp</code>, <code>src/engine/hydraulics/fv/ExplicitFvSolver.cpp</code></li><li><code>src/engine/2d/</code> (marching scheme and coupling), <code>src/engine/hydrology/RDII.cpp</code>, <code>src/engine/core/SimulationOptions.hpp</code></li></ul></li><li>OpenSWMM engine reference manuals (Vol. II — Hydraulics, ch. 3, 7, 9; Vol. I — Hydrology, ch. 7).</li></ol>',8)])])}const p=o(i,[["render",r]]);export{u as __pageData,p as default};
